        //        SOFTWARE.

        // Sanitize
        if (salt == null || challenge == null) {
            throw new IllegalArgumentException("Password, salt, and challenge are required");
        }

        // Compute
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");

            String secretString = password + salt;
            byte[] secretHash = digest.digest(secretString.getBytes(StandardCharsets.UTF_8));
            String encodedSecret = Base64.getEncoder().encodeToString(secretHash);

            String resultString = encodedSecret + challenge;
            byte[] resultHash = digest.digest(resultString.getBytes(StandardCharsets.UTF_8));

            return Base64.getEncoder().encodeToString(resultHash);
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("Could not find expected message digest to compute auth", e);
        }
    }


    @Override
    public void onOpen(WebSocket webSocket, Response response) {
        log.debug("WebSocket opened: {}", response.message());
    }

    @Override
    public void onMessage(WebSocket webSocket, String text) {
        log.debug("Received text: {}", text);
        ObsV5Message response = gson.fromJson(text, ObsV5Message.class);
        if (response.op == 0) {
            HelloData helloData = gson.fromJson(response.d, HelloData.class);
            String authResponse = computeAuthentication(helloData.authentication.salt, helloData.authentication.challenge);
            log.debug("Sending Identify request");
            IdentifyRequest identifyRequest = new IdentifyRequest(authResponse);
            webSocket.send(gson.toJson(identifyRequest));
        } else if (response.op == 2) { // Opcode 2: Identified (Success after Identify/Auth)
            log.info("OBS successfully Identified. Connection ready.");
            client.setConnected(true);
        } else if (response.op == 7) { // Opcode 7: RequestResponse
            RequestResponse responseData = gson.fromJson(response.d, RequestResponse.class);
            if (Objects.equals(responseData.requestId, "runelite-duration-req")) {
                handleClipResponse(responseData);
                return;
            }
            if (Objects.equals(responseData.requestType, "GetReplayBufferStatus")) {
                // healthcheck response
                HealthResponse healthResponse = gson.fromJson(responseData.responseData.toString(), HealthResponse.class);
                if (healthResponse.outputActive) {
                    exceptionsDisplay.clearObsException();
                }
                else
                {
                    exceptionsDisplay.setObsException(new ObsException("OBS Replay Buffer is not active!"));
                }
            }
        }
    }

    private void handleClipResponse(RequestResponse response) {
        if (response.requestStatus == null || !response.requestStatus.result) {
            // obs-websocket itself refused, most often because the Replay Buffer Pro vendor is not registered.
            clipFailed(response.requestStatus == null ? null : response.requestStatus.comment,
                "Make sure the Replay Buffer Pro OBS plugin is installed and up to date.");
            return;
        }
        ClipResult result = gson.fromJson(response.responseData.get("responseData"), ClipResult.class);
        if (result == null || !result.accepted) {
            String error = result == null || result.error == null ? "" : result.error;
            clipFailed(error, CLIP_ERROR_HELP.getOrDefault(error, "Check that OBS and Replay Buffer Pro are running."));
            return;
        }
        if (result.clamped) {
            log.warn("Clip shortened to the {}s OBS replay buffer", result.durationSeconds);
            exceptionsDisplay.showChatMessage("Your replay clip was shortened to " + ActivityCapture.duration(result.durationSeconds)
                + ", the length of your OBS replay buffer. Increase it in OBS to capture whole activities.");
        }
    }

    private void clipFailed(String reason, String help) {
        log.warn("OBS refused the clip request: {}", reason);
        exceptionsDisplay.showChatMessage("OBS couldn't save your replay clip. " + help);
    }

    @Override
    public void onClosing(WebSocket webSocket, int code, String reason) {
        log.info("WebSocket closed with code: {}, reason: {}", code, reason);
        client.setConnected(false);

        if (code != 1000) {
            exceptionsDisplay.setObsException(new ObsException(
                MessageFormat.format("OBS WebSocket connection closed unexpectedly: {0}", reason)
            ));
        }
    }

    @Override
    public void onFailure(WebSocket webSocket, Throwable t, Response response) {
        client.setConnected(false);
        log.info("WebSocket failed: {}", t.getMessage());
        exceptionsDisplay.setObsException(new ObsException(
                "Unable to connect to the OBS WebSocket Server. Is OBS running and configured?"
        ));
    }


}

package com.savereplaybufferforobs;

import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.ScheduledThreadPoolExecutor;
import java.util.concurrent.TimeUnit;
import net.runelite.api.GameState;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameStateChanged;
import org.junit.After;
import org.junit.Test;
import static org.junit.Assert.*;

public class ActivityCaptureTest
{
    private final SaveReplayBufferForObsConfig config = new SaveReplayBufferForObsConfig()
    {
        public boolean captureCox() { return true; }
        public boolean captureTob() { return true; }
        public boolean captureToa() { return true; }
        public boolean captureInferno() { return true; }
        public boolean captureColosseum() { return true; }
        public boolean captureDoom() { return true; }
        public boolean captureTfa() { return true; }
    };
    private final SaveReplayBufferForObsConfig disabled = new SaveReplayBufferForObsConfig() { };
    private static final WorldPoint OUTSIDE = new WorldPoint(3200, 3200, 0);
    private long now;
    private final List<Runnable> callbacks = new ArrayList<>();
    private final List<Long> delays = new ArrayList<>();
    private final List<Long> dueTimes = new ArrayList<>();
    private final List<Integer> requests = new ArrayList<>();
    private final List<ScheduledFuture<?>> futures = new ArrayList<>();
    private final ScheduledThreadPoolExecutor scheduler = new ScheduledThreadPoolExecutor(1)
    {
        @Override
        public ScheduledFuture<?> schedule(Runnable command, long delay, TimeUnit unit)
        {
            callbacks.add(command);
            long delayMillis = unit.toMillis(delay);
            delays.add(delayMillis);
            dueTimes.add(now + TimeUnit.MILLISECONDS.toNanos(delayMillis));
            ScheduledFuture<?> future = super.schedule(command, 1, TimeUnit.DAYS);
            futures.add(future);
            return future;
        }
    };
    private final ActivityCapture capture = new ActivityCapture(scheduler, () -> now, requests::add, message -> { });

    @After
    public void close()
    {
        scheduler.shutdownNow();
    }

    @Test
    public void eachActivitySavesFromEntryUntilLeaving()
    {
        for (ActivityCapture.Activity activity : ActivityCapture.Activity.values())
        {
            capture.cancel();
            callbacks.clear();
            dueTimes.clear();
            now = 0;
            enter(activity);
            now = TimeUnit.SECONDS.toNanos(60);
            capture.locationChanged(OUTSIDE, false, false, config);
            assertEquals(activity.toString(), 1, callbacks.size());
            run(0);
            assertEquals(activity.toString(), Integer.valueOf(62), requests.get(requests.size() - 1));
        }
    }

    @Test
    public void roomChangesDelvesAndTheColosseumChestKeepOneRecording()
    {
        capture.locationChanged(region(15698), false, false, config);
        capture.locationChanged(region(15700), false, false, config); // ToA room change.
        capture.locationChanged(region(15184), false, false, config);
        capture.locationChanged(new WorldPoint(1300, 9560, 0), false, false, config); // Straight into Doom ends ToA.
        capture.locationChanged(new WorldPoint(3400, 6400, 0), false, false, config); // Next delve.
        capture.locationChanged(new WorldPoint(3520, 6400, 0), false, false, config);
        assertEquals(1, callbacks.size());

        capture.locationChanged(new WorldPoint(1820, 3100, 0), false, false, config); // Colosseum arena ends Doom.
        capture.locationChanged(new WorldPoint(1800, 3080, 0), false, false, config); // Reward chest, same region.
        assertEquals(2, callbacks.size());
        capture.locationChanged(OUTSIDE, false, false, config);
        assertEquals(3, callbacks.size());

        capture.locationChanged(region(16471), false, false, config); // TFA's first room.
        capture.locationChanged(region(16214), false, false, config); // A boss room.
        assertEquals(3, callbacks.size());
        capture.locationChanged(region(16470), false, false, config); // Back out to the lobby.
        assertEquals(4, callbacks.size());

        capture.locationChanged(region(16471), false, true, config); // Spectating another team.
        capture.locationChanged(region(16470), false, false, config);
        assertEquals(4, callbacks.size());
    }

    @Test
    public void paddingAndSchedulingLagAreIncluded()
    {
        capture.locationChanged(region(15698), false, false, config);
        now = TimeUnit.SECONDS.toNanos(100);
        capture.locationChanged(OUTSIDE, false, false, config);
        assertEquals(Long.valueOf(1000), delays.get(0)); // 1% post-padding.
        assertTrue(requests.isEmpty());
        now = TimeUnit.MILLISECONDS.toNanos(101_500); // 500 ms scheduler lag.
        run(0);
        assertEquals(Integer.valueOf(103), requests.get(0)); // 101.5s elapsed plus 1% pre-padding.
    }

    @Test
    public void disabledActivitiesNeverRecordAndTurningOneOffDiscardsTheRecording()
    {
        capture.locationChanged(region(15698), false, false, disabled);
        assertFalse(capture.inEnabledActivity(disabled));
        capture.locationChanged(OUTSIDE, false, false, disabled);
        assertTrue(callbacks.isEmpty());

        capture.locationChanged(region(15698), false, false, config);
        assertTrue(capture.inEnabledActivity(config));
        capture.locationChanged(OUTSIDE, false, false, disabled);
        assertTrue(callbacks.isEmpty());
        assertFalse(capture.inEnabledActivity(config));
    }

    @Test
    public void logoutAndHopEndTheRecordingButALostConnectionKeepsIt() throws Exception
    {
        SaveReplayBufferForObsPlugin plugin = new SaveReplayBufferForObsPlugin();
        setField(plugin, "activityCapture", capture);
        setField(plugin, "config", config);
        GameStateChanged state = new GameStateChanged();
        enter(ActivityCapture.Activity.TOB);
        now = TimeUnit.SECONDS.toNanos(30);
        state.setGameState(GameState.CONNECTION_LOST);
        plugin.onGameStateChanged(state);
        enter(ActivityCapture.Activity.TOB); // Reconnected into the same raid.
        assertTrue(callbacks.isEmpty());

        now = TimeUnit.SECONDS.toNanos(60);
        state.setGameState(GameState.HOPPING);
        plugin.onGameStateChanged(state);
        assertEquals(1, callbacks.size());
        run(0);
        assertEquals(Integer.valueOf(62), requests.get(0));

        enter(ActivityCapture.Activity.INFERNO); // Logged back in inside the Inferno after pausing.
        now = TimeUnit.SECONDS.toNanos(1860);
        state.setGameState(GameState.LOGIN_SCREEN);
        plugin.onGameStateChanged(state);
        assertEquals(2, callbacks.size());
        run(1);
        assertEquals(Integer.valueOf(1836), requests.get(1)); // Only the time since logging back in.
    }

    @Test
    public void aSaveSurvivesEnteringTheNextActivityButShutdownCancelsIt() throws Exception
    {
        enter(ActivityCapture.Activity.TOA);
        now = TimeUnit.SECONDS.toNanos(100);
        enter(ActivityCapture.Activity.DOOM);
        run(0);
        assertEquals(1, requests.size());

        SaveReplayBufferForObsPlugin plugin = new SaveReplayBufferForObsPlugin()
        {
            @Override
            public void clearObsException() { }
        };
        setField(plugin, "activityCapture", capture);
        now = TimeUnit.SECONDS.toNanos(200);
        capture.locationChanged(OUTSIDE, false, false, config);
        plugin.shutDown();
        assertTrue(futures.get(1).isCancelled()); // The pending Doom save.
    }

    private void enter(ActivityCapture.Activity activity)
    {
        switch (activity)
        {
            case COX:
                capture.locationChanged(OUTSIDE, true, false, config);
                break;
            case TOB:
                capture.locationChanged(region(12869), false, false, config);
                break;
            case TOA:
                capture.locationChanged(region(15698), false, false, config);
                break;
            case INFERNO:
                capture.locationChanged(region(9043), false, false, config);
                break;
            case COLOSSEUM:
                capture.locationChanged(new WorldPoint(1820, 3100, 0), false, false, config);
                break;
            case DOOM:
                capture.locationChanged(new WorldPoint(1300, 9560, 0), false, false, config);
                break;
            case TFA:
                capture.locationChanged(region(16471), false, false, config);
                break;
            default:
                throw new AssertionError(activity);
        }
    }

    private void run(int index)
    {
        now = Math.max(now, dueTimes.get(index));
        callbacks.get(index).run();
    }

    private static void setField(Object object, String name, Object value) throws Exception
    {
        Field field = SaveReplayBufferForObsPlugin.class.getDeclaredField(name);
        field.setAccessible(true);
        field.set(object, value);
    }

    private static WorldPoint region(int id)
    {
        return new WorldPoint((id >> 8) * 64, (id & 255) * 64, 0);
    }
}

